# jax.nn functions (R/nn.R). Expected values were produced by jax 0.12.0.1 on CPU (x64
# disabled); arrays are listed in C order as list(shape, values, dtype).

nnt_c_ravel <- function(x) {
  d <- dim(x)
  if (length(d) <= 1L) return(as.vector(x))
  as.vector(aperm(x, length(d):1))
}

# Exact comparison (tol = 0) unless a relative tolerance is given.
nnt_expect <- function(x, ref, tol = 0) {
  expect_identical(jaxR::dtype(x), ref[[3L]])
  expect_identical(as.integer(dim(x)), as.integer(ref[[1L]]))
  got <- nnt_c_ravel(as.array(x))
  if (is.logical(ref[[2L]])) return(expect_identical(as.logical(got), ref[[2L]]))
  if (tol == 0) expect_identical(as.numeric(got), as.numeric(ref[[2L]]))
  else expect_equal(as.numeric(got), as.numeric(ref[[2L]]), tolerance = tol)
}

# Array from C order values.
nnt_arr <- function(values, shape, dtype = "float32") jnp_reshape(jnp_array(values, dtype), shape)

# Inputs of the attention tests: jax.random.split(PRNGKey(7), 4) and normal draws.
nnt_attention_inputs <- function() {
  ks <- random_split(random_PRNGKey(7), 4L)
  k <- function(i) lax_index_in_dim(ks, i, 0L, keepdims = FALSE)
  list(q = random_normal(k(0L), c(2, 3, 4, 5)), k = random_normal(k(1L), c(2, 6, 2, 5)),
       v = random_normal(k(2L), c(2, 6, 2, 5)), bias = random_normal(k(3L), c(1, 4, 3, 6)),
       k4 = random_normal(k(1L), c(2, 6, 4, 5)))
}

