nnt_x <- function() jnp_array(c(-2.5, -1, -0.5, 0, 0.3, 1, 2, 7), "float32")

test_that("activation functions match jax.nn", {
  skip_if_no_backend()
  x <- nnt_x()
  for (nm in c("relu", "relu6", "squareplus", "softplus", "sparse_plus", "soft_sign", "sigmoid",
               "sparse_sigmoid", "silu", "mish", "log_sigmoid", "elu", "leaky_relu", "hard_tanh",
               "celu", "selu", "gelu", "hard_sigmoid", "hard_silu", "tanh")) {
    nnt_expect(get(paste0("nn_", nm))(x), nnt_ref[[nm]])
  }
  nnt_expect(nn_swish(x), nnt_ref$silu)
  nnt_expect(nn_hard_swish(x), nnt_ref$hard_silu)
  nnt_expect(nn_identity(x), list(8L, as.array(x), "float32"))
  nnt_expect(nn_squareplus(x, 1.5), nnt_ref$squareplus_b1)
  nnt_expect(nn_elu(x, 0.5), nnt_ref$elu_a)
  nnt_expect(nn_leaky_relu(x, 0.2), nnt_ref$leaky_relu_s)
  nnt_expect(nn_celu(x, 2), nnt_ref$celu_a, tol = 1e-6)
  nnt_expect(nn_gelu(x, approximate = FALSE), nnt_ref$gelu_exact)
  nnt_expect(nn_log1mexp(jnp_array(c(0.1, 0.5, 0.69, 0.7, 2, 10), "float32")), nnt_ref$log1mexp)
  x24 <- nnt_arr(0:7, c(2, 4)) / 4 - 1
  nnt_expect(nn_glu(x24), nnt_ref$glu_last)
  nnt_expect(nn_glu(x24, axis = 0L), nnt_ref$glu_0)
  expect_error(nn_glu(nnt_arr(1:3, 3)), "divisible by 2")
})

test_that("activation dtypes follow JAX promotion", {
  skip_if_no_backend()
  xi <- jnp_array(c(-3L, 0L, 2L, 7L))
  nnt_expect(nn_relu(xi), nnt_ref$relu_int)
  nnt_expect(nn_relu6(xi), nnt_ref$relu6_int)
  nnt_expect(nn_hard_tanh(xi), nnt_ref$hard_tanh_int)
  nnt_expect(nn_gelu(xi), nnt_ref$gelu_int)
  nnt_expect(nn_softplus(xi), nnt_ref$softplus_int)
  # R scalars are weakly typed
  expect_identical(jaxR::dtype(nn_relu(2)), "float32")
  expect_identical(jaxR::dtype(nn_sigmoid(jnp_array(c(1, 2), "float16"))), "float16")
  expect_identical(jaxR::dtype(nn_gelu(jnp_array(c(1, 2), "bfloat16"))), "bfloat16")
})

test_that("activations under jit and vmap equal the eager values", {
  skip_if_no_backend()
  x <- nnt_x()
  nnt_expect(jit(function(v) nn_gelu(v))(x), nnt_ref$gelu)
  nnt_expect(jit(function(v) nn_selu(v))(x), nnt_ref$selu)
  nnt_expect(jit(function(v) nn_softplus(v))(x), nnt_ref$softplus)
  m <- jnp_reshape(x, c(2, 4))
  got <- vmap(function(r) nn_mish(r))(m)
  expect_identical(nnt_c_ravel(as.array(got)), nnt_ref$mish[[2L]])
  got <- vmap(function(r) nn_glu(r))(m)
  expect_equal(as.array(got), rbind(as.array(nn_glu(lax_index_in_dim(m, 0L, keepdims = FALSE))),
                                    as.array(nn_glu(lax_index_in_dim(m, 1L, keepdims = FALSE)))))
})

test_that("custom JVP rules match jax.grad", {
  skip_if_no_backend()
  gx <- jnp_array(c(-1.5, 0, 0.5, 6, 7), "float32")
  for (nm in c("relu", "relu6", "softplus", "silu", "mish", "log_sigmoid", "elu", "celu", "selu",
               "gelu", "hard_sigmoid", "hard_silu", "leaky_relu", "hard_tanh", "sparse_plus",
               "sparse_sigmoid", "soft_sign", "squareplus", "sigmoid")) {
    f <- get(paste0("nn_", nm))
    nnt_expect(vmap(grad(function(v) f(v)))(gx), nnt_ref[[paste0("grad_", nm)]])
  }
  # derivative of relu at 0 is 0; of relu6 at 0 and 6 is 0
  expect_identical(as.numeric(as.array(grad(nn_relu)(0))), 0)
  expect_identical(as.numeric(as.array(grad(nn_relu6)(0))), 0)
  expect_identical(as.numeric(as.array(grad(nn_relu6)(6))), 0)
  nnt_expect(vmap(grad(grad(nn_relu)))(gx), nnt_ref$grad2_relu)
  nnt_expect(vmap(grad(nn_log1mexp))(jnp_array(c(0.1, 0.5, 0.69, 0.7, 2, 10), "float32")),
             nnt_ref$grad_log1mexp, tol = 1e-6)
  # forward mode uses the same rules
  out <- jvp(nn_relu, list(jnp_array(c(-1, 0, 2), "float32")), list(jnp_array(c(1, 1, 1), "float32")))
  expect_identical(as.vector(as.array(out[[2L]])), c(0, 0, 1))
})

test_that("gradients agree with finite differences in float64", {
  skip_if_no_backend()
  old <- enable_x64(TRUE)
  on.exit(jax_config_update("jax_enable_x64", old), add = TRUE)
  x <- as_jax(c(-1.3, -0.4, 0.2, 0.9, 2.1), "float64")
  for (f in list(nn_softplus, nn_mish, nn_selu, nn_celu, nn_silu, nn_log_sigmoid, nn_squareplus,
                 function(v) nn_gelu(v, FALSE), nn_gelu, nn_elu, nn_soft_sign)) {
    check_grad_fd(function(v) jnp_sum(f(v)), x)
  }
  w <- as_jax(c(1, -2, 0.5, 3, 1), "float64")
  check_grad_fd(function(v) jnp_sum(nn_softmax(v) * w), x)
  check_grad_fd(function(v) jnp_sum(nn_log_softmax(v) * w), x)
  check_grad_fd(function(v) nn_logsumexp(v), x)
  check_grad_fd(function(v) jnp_sum(nn_standardize(v) * w), x)
  check_grad_fd(function(v) jnp_sum(nn_glu(jnp_concatenate(list(v, v * 2))) * w), x)
  check_grad_fd(function(v) jnp_sum(nn_log1mexp(v + 2)), x)
  # second order
  check_grad_fd(function(v) jnp_sum(grad(function(y) jnp_sum(nn_softplus(y)))(v)), x)
  # attention with respect to the query; the softmax runs in float32 (as in JAX), so the
  # differences use a larger step
  q <- as_jax(c(0.3, -0.2, 0.5, 1.1, -0.7, 0.4), "float64")
  kv <- jnp_reshape(as_jax(seq(-1, 1, length.out = 6), "float64"), c(3, 1, 2))
  check_grad_fd(function(v) jnp_sum(nn_dot_product_attention(jnp_reshape(v, c(3, 1, 2)), kv, kv,
                                                              is_causal = TRUE)^2L), q,
                eps = 1e-3, tolerance = 1e-3)
})

test_that("softmax, log_softmax, logsumexp and logmeanexp match jax.nn", {
  skip_if_no_backend()
  xs <- nnt_arr(c(1, 2, 3, -1, 0.5, 4), c(2, 3))
  w <- jnp_reshape(jnp_array(c(TRUE, FALSE, TRUE, TRUE, TRUE, FALSE)), c(2, 3))
  nnt_expect(nn_softmax(xs), nnt_ref$softmax_last)
  nnt_expect(nn_softmax(xs, axis = 0L), nnt_ref$softmax_0)
  nnt_expect(nn_softmax(xs, axis = NULL), nnt_ref$softmax_all)
  nnt_expect(nn_softmax(xs, where = w), nnt_ref$softmax_where)
  nnt_expect(nn_log_softmax(xs), nnt_ref$log_softmax_last)
  nnt_expect(nn_log_softmax(xs, axis = 0L), nnt_ref$log_softmax_0)
  nnt_expect(nn_log_softmax(xs, where = w), nnt_ref$log_softmax_where)
  nnt_expect(nn_logsumexp(xs), nnt_ref$logsumexp_all)
  nnt_expect(nn_logsumexp(xs, axis = 1L), nnt_ref$logsumexp_1)
  nnt_expect(nn_logsumexp(xs, axis = 0L, keepdims = TRUE), nnt_ref$logsumexp_keep)
  b <- nnt_arr(c(1, -2, 0.5, 0, 1, 1), c(2, 3))
  nnt_expect(nn_logsumexp(xs, axis = 1L, b = b), nnt_ref$logsumexp_b)
  rs <- nn_logsumexp(xs, axis = 1L, b = b, return_sign = TRUE)
  nnt_expect(rs[[1L]], nnt_ref$logsumexp_rs_r)
  nnt_expect(rs[[2L]], nnt_ref$logsumexp_rs_s)
  nnt_expect(nn_logsumexp(xs, axis = 1L, where = w), nnt_ref$logsumexp_where)
  nnt_expect(nn_logmeanexp(xs, axis = 1L), nnt_ref$logmeanexp_1)
  nnt_expect(nn_logmeanexp(xs), nnt_ref$logmeanexp_all)
  nnt_expect(nn_logmeanexp(xs, axis = 1L, where = w), nnt_ref$logmeanexp_where)
  # jit and vmap
  nnt_expect(jit(function(v) nn_softmax(v))(xs), nnt_ref$softmax_last)
  nnt_expect(jit(function(v, m) nn_log_softmax(v, where = m))(xs, w), nnt_ref$log_softmax_where)
  nnt_expect(vmap(function(r) nn_softmax(r))(xs), nnt_ref$softmax_last)
  nnt_expect(vmap(function(r) nn_logsumexp(r))(xs), nnt_ref$logsumexp_1)
  nnt_expect(vmap(function(r, m) nn_softmax(r, where = m))(xs, w), nnt_ref$softmax_where)
})

test_that("softmax derivatives match jax.grad with and without the custom JVP", {
  skip_if_no_backend()
  v3 <- jnp_array(c(1, 2, 3), "float32")
  wt <- jnp_array(c(1, 2, 3), "float32")
  loss <- function(v) jnp_sum(nn_softmax(v) * wt)
  nnt_expect(grad(loss)(v3), nnt_ref$grad_softmax)
  nnt_expect(grad(function(v) jnp_sum(nn_softmax(v, where = c(TRUE, FALSE, TRUE)) * wt))(v3),
             nnt_ref$grad_softmax_where)
  dir <- jnp_array(c(0.5, -1, 2), "float32")
  nnt_expect(jvp(function(v) nn_softmax(v), list(v3), list(dir))[[2L]], nnt_ref$jvp_softmax, tol = 1e-6)
  nnt_expect(grad(function(v) jnp_sum(nn_log_softmax(v) * wt))(v3), nnt_ref$grad_log_softmax,
             tol = 1e-6)
  # jax_softmax_custom_jvp = True: the custom rule y * (x_dot - sum(y * x_dot))
  cfg <- jaxR:::.jx
  old <- cfg$config["jax_softmax_custom_jvp"]
  cfg$config$jax_softmax_custom_jvp <- TRUE
  on.exit(cfg$config["jax_softmax_custom_jvp"] <- old, add = TRUE)
  nnt_expect(grad(loss)(v3), nnt_ref$grad_softmax_cj)
  nnt_expect(jvp(function(v) nn_softmax(v), list(v3), list(dir))[[2L]], nnt_ref$jvp_softmax_cj)
  xs <- nnt_arr(c(1, 2, 3, -1, 0.5, 4), c(2, 3))
  w <- jnp_reshape(jnp_array(c(TRUE, FALSE, TRUE, TRUE, TRUE, FALSE)), c(2, 3))
  nnt_expect(nn_softmax(xs, where = w), nnt_ref$softmax_cj_where)
  nnt_expect(vmap(function(r) nn_softmax(r))(xs), nnt_ref$softmax_last)
  # a boolean mask passes through the custom JVP as a differentiable argument
  mask3 <- c(TRUE, FALSE, TRUE)
  nnt_expect(grad(function(v) jnp_sum(nn_softmax(v, where = mask3) * wt))(v3),
             nnt_ref$grad_softmax_where, tol = 1e-6)
  tw <- jvp(function(v) nn_softmax(v, where = mask3), list(v3), list(dir))[[2L]]
  y <- as.vector(as.array(nn_softmax(v3, where = mask3)))
  d <- as.vector(as.array(dir)) * mask3
  expect_equal(as.vector(as.array(tw)), y * (d - sum(y * d)), tolerance = 1e-6)
  nnt_expect(vmap(function(r, m) nn_softmax(r, where = m))(xs, w), nnt_ref$softmax_where, tol = 1e-6)
  nnt_expect(jit(function(v, m) nn_softmax(v, where = m))(xs, w), nnt_ref$softmax_where, tol = 1e-6)
  cfg$config["jax_softmax_custom_jvp"] <- old
  nnt_expect(grad(function(v) nn_logsumexp(v))(xs), nnt_ref$grad_logsumexp)
})

test_that("standardize matches jax.nn", {
  skip_if_no_backend()
  x3 <- nnt_arr(c(0.5, -1, 2, 3, 1, 1.5, -2, 0, 4, 2, 0, -1, 0.25, 0.75, 1, 2), c(2, 2, 4))
  nnt_expect(nn_standardize(x3), nnt_ref$std_last)
  nnt_expect(nn_standardize(x3, axis = c(0L, 2L)), nnt_ref$std_axes)
  nnt_expect(nn_standardize(x3, axis = 1L, algorithm = "stable"), nnt_ref$std_stable)
  nnt_expect(nn_standardize(x3, mean = 1, variance = 4), nnt_ref$std_mean_var)
  nnt_expect(nn_standardize(x3, where = x3 > 0), nnt_ref$std_where)
  nnt_expect(nn_standardize(x3, axis = NULL, epsilon = 0.5), nnt_ref$std_eps)
  nnt_expect(grad(function(v) jnp_sum(nn_standardize(v) * jnp_arange(4)))(x3),
             nnt_ref$grad_standardize, tol = 1e-6)
  expect_error(nn_standardize(x3, algorithm = "slow"), "Unknown algorithm 'slow'")
})

test_that("one_hot matches jax.nn", {
  skip_if_no_backend()
  nnt_expect(nn_one_hot(c(0L, 1L, 2L, -1L, 3L), 3L), nnt_ref$one_hot)
  idx <- nnt_arr(c(0L, 2L, 1L, 1L), c(2, 2), "int32")
  nnt_expect(nn_one_hot(idx, 3, axis = 0L), nnt_ref$one_hot_ax0)
  nnt_expect(nn_one_hot(idx, 3, axis = 1L), nnt_ref$one_hot_ax1)
  nnt_expect(nn_one_hot(c(2L, 0L), 4, dtype = "int32"), nnt_ref$one_hot_int)
  expect_warning(out <- nn_one_hot(c(1, 2), 3), "should be integer-typed")
  nnt_expect(out, nnt_ref$one_hot_float)
  # jit, vmap and a named axis
  nnt_expect(jit(function(i) nn_one_hot(i, 3L))(c(0L, 1L, 2L, -1L, 3L)), nnt_ref$one_hot)
  nnt_expect(vmap(function(i) nn_one_hot(i, 3L))(c(0L, 1L, 2L, -1L, 3L)), nnt_ref$one_hot)
  # each mapped element is compared with its own axis index
  got <- vmap(function(i) nn_one_hot(i, 3L, axis = "b"), axis_name = "b")(
    nnt_arr(c(0L, 2L, 1L, 1L, 2L, 0L), c(3, 2), "int32"))
  nnt_expect(got, list(c(3, 2), c(1, 0, 1, 1, 1, 0), "float32"))
  expect_error(vmap(function(i) nn_one_hot(i, 4L, axis = "b"), axis_name = "b")(c(0L, 2L, 1L)),
               "Expected num_classes to match the size of axis b")
})

test_that("dot_product_attention matches jax.nn", {
  skip_if_no_backend()
  a <- nnt_attention_inputs()
  q <- a$q
  k <- a$k
  v <- a$v
  mask <- jnp_reshape(jnp_arange(18L) %% 4L, c(1, 1, 3, 6)) != 1L
  nnt_expect(nn_dot_product_attention(q, k, v), nnt_ref$att_plain)
  nnt_expect(nn_dot_product_attention(q, k, v, is_causal = TRUE), nnt_ref$att_causal)
  nnt_expect(nn_dot_product_attention(q, k, v, bias = a$bias, mask = mask, scale = 0.3),
             nnt_ref$att_bias_mask)
  nnt_expect(nn_dot_product_attention(q, k, v, local_window_size = c(1, 2)), nnt_ref$att_window)
  nnt_expect(nn_dot_product_attention(q, k, v, local_window_size = 1), nnt_ref$att_window1)
  nnt_expect(nn_dot_product_attention(q, k, v, query_seq_lengths = c(2L, 3L),
                                      key_value_seq_lengths = c(4L, 6L)), nnt_ref$att_seqlen)
  r <- nn_dot_product_attention(q, k, v, is_causal = TRUE, return_residual = TRUE)
  nnt_expect(r[[1L]], nnt_ref$att_res_out)
  nnt_expect(r[[2L]], nnt_ref$att_res_lse)
  first <- function(t) lax_index_in_dim(t, 0L, keepdims = FALSE)
  nnt_expect(nn_dot_product_attention(first(q), first(k), first(v)), nnt_ref$att_3d)
  nnt_expect(nn_dot_product_attention(q, a$k4, a$k4, bias = jnp_broadcast_to(a$bias, c(2, 4, 3, 6))),
             nnt_ref$att_mha_bias_heads, tol = 1e-6)
  nnt_expect(nn_dot_product_attention(q, k, v, implementation = "xla"), nnt_ref$att_plain)
  nnt_expect(jit(function(a1, a2, a3) nn_dot_product_attention(a1, a2, a3, is_causal = TRUE))(q, k, v),
             nnt_ref$att_causal, tol = 1e-6)
  nnt_expect(grad(function(qq) jnp_sum(nn_dot_product_attention(qq, k, v, is_causal = TRUE)^2L))(q),
             nnt_ref$att_grad_q, tol = 1e-5)
  # vmap over the batch equals the batched call
  got <- vmap(function(a1, a2, a3) nn_dot_product_attention(a1, a2, a3, is_causal = TRUE))(q, k, v)
  nnt_expect(got, nnt_ref$att_causal, tol = 1e-6)
  expect_error(nn_dot_product_attention(q, k, jnp_astype(v, "float16")), "value dtype should be float32")
  expect_error(nn_dot_product_attention(q, k, v, mask = jnp_ones(c(1, 1, 3, 6))),
               "mask dtype should be bool")
  expect_error(nn_dot_product_attention(q, k, v, query_seq_lengths = c(1L, 2L, 3L)),
               "query_seq_lengths shape should be \\[2\\]: but got \\(3,\\)")
  expect_error(nn_dot_product_attention(jnp_ones(c(2, 3, 3, 5)), k, v),
               "multiple of key/value heads, but got 3 vs 2")
  expect_error(nn_dot_product_attention(q, k, v, implementation = "flash"),
               "Unsupported implementation option: flash")
})

test_that("scaled_matmul and scaled_dot_general match jax.nn", {
  skip_if_no_backend()
  a <- nnt_arr(c(1, 2, 3, 4), c(1, 1, 4))
  b <- nnt_arr(c(4, 5, 6, 7, 1, 0, 2, -1), c(1, 2, 4))
  as_ <- nnt_arr(c(0.5, 2), c(1, 1, 2))
  bs <- nnt_arr(c(0.5, 1, 3, 0.25), c(1, 2, 2))
  nnt_expect(nn_scaled_matmul(a, b, as_, bs), nnt_ref$scaled_matmul)
  lhs <- nnt_arr(0:23, c(2, 3, 4))
  rhs <- nnt_arr(0:15, c(2, 4, 2)) / 3
  nnt_expect(nn_scaled_dot_general(lhs, rhs, list(list(2L, 1L), list(0L, 0L))), nnt_ref$sdg)
  expect_error(nn_scaled_matmul(a, b, as_, nnt_arr(1, c(1, 1, 1))), "matching batch \\(B\\) and contract")
  expect_error(nn_scaled_matmul(jnp_ones(c(1, 4)), b, as_, bs), "3-dimensional")
  expect_error(nn_scaled_dot_general(lhs, rhs, list(list(2L, 1L), list(0L, 0L)), configs = list(1)),
               "float8")
})
